#include <bits/stdc++.h>
using namespace std;

long long mod = 998244353;

vector<vector<long long>> enumFIF(int n, long long mod) {
    vector<long long> f(n + 1), invf(n + 1);
    f[0] = 1;
    for (int i = 1; i <= n; i++) {
        f[i] = f[i - 1] * i % mod;
    }
    long long a = f[n], b = mod;
    long long p = 1, q = 0;
    while (b > 0) {
        long long c = a / b;
        long long d = a;
        a = b;
        b = d % b;
        d = p;
        p = q;
        q = d - c * q;
    }
    invf[n] = (p < 0 ? p + mod : p);
    for (int i = n - 1; i >= 0; i--) {
        invf[i] = invf[i + 1] * (i + 1) % mod;
    }
    return {f, invf};
}

long long C(int n, int r, const vector<long long>& f, const vector<long long>& invf) {
    if (n < 0 || r < 0 || r > n) return 0;
    return f[n] * invf[r] % mod * invf[n - r] % mod;
}

long long pow_mod(long long a, int n, long long mod) {
    long long res = 1;
    long long base = a % mod;
    for (int i = 0; i < n; i++) {
        res = res * base % mod;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, K, L;
    cin >> n >> K >> L;
    vector<vector<long long>> fif = enumFIF(10000, mod);
    vector<long long> muls(n + 1, 0);
    for (int i = K; i <= n; i++) {
        long long m = C(n, i, fif[0], fif[1]);
        for (int j = i; j <= n; j++) {
            long long sign = ((j - i) % 2 == 0) ? 1 : -1;
            long long val = m * C(n - i, n - j, fif[0], fif[1]) % mod * sign;
            muls[j] = (muls[j] + val) % mod;
        }
    }
    long long ans = 0;
    for (int i = K; i <= n; i++) {
        long long term = pow_mod(2, i, mod) * fif[0][i] % mod * fif[1][i] % mod
                * fif[1][2 * i + 1] % mod * muls[i] % mod;
        ans = (ans + term) % mod;
    }
    ans = (ans + mod) % mod;
    cout << ans * L % mod << "\n";
    return 0;
}

